SELECT id, name, price, stock_quantity, image_url, description
FROM products
WHERE id = #{id}

SELECT id, name, price, stock_quantity, image_url, description FROM products
ORDER BY price ASC, id DESC ORDER BY price DESC, id DESC ORDER BY name ASC, id DESC ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE products
SET stock_quantity = stock_quantity - #{quantity}
WHERE id = #{productId}
  AND stock_quantity >= #{quantity}

UPDATE products
SET stock_quantity = stock_quantity + #{quantity}
WHERE id = #{productId}
